package com.ascensionshardmining;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Notification;
import net.runelite.client.config.Range;

@ConfigGroup("ascension-shard-mining")
public interface AscensionShardMiningConfig extends Config
{
	@ConfigSection(
		name = "Rocks",
		description = "Options for Ascension rock highlights",
		position = 0
	)
	String rocksSection = "rocksSection";

	@ConfigItem(
		keyName = "highlightRocks",
		name = "Highlight rocks",
		description = "Configures whether or not to highlight active Ascension rocks",
		position = 1,
		section = rocksSection
	)
	default boolean highlightRocks()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "rockColor",
		name = "Rock color",
		description = "Color to highlight active Ascension rocks",
		position = 2,
		section = rocksSection
	)
	default Color rockColor()
	{
		return Color.CYAN;
	}

	@ConfigSection(
		name = "Sprite",
		description = "Options for Ascension sprite highlights",
		position = 10
	)
	String spriteSection = "spriteSection";

	@ConfigItem(
		keyName = "highlightSprite",
		name = "Highlight sprite",
		description = "Configures whether or not to highlight active Ascension sprites",
		position = 11,
		section = spriteSection
	)
	default boolean highlightSprite()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "spriteColor",
		name = "Sprite color",
		description = "Color to highlight active Ascension sprites",
		position = 12,
		section = spriteSection
	)
	default Color spriteColor()
	{
		return Color.MAGENTA;
	}

	@ConfigSection(
		name = "Rendering",
		description = "Options for rendering highlights",
		position = 20
	)
	String renderingSection = "renderingSection";

	@ConfigItem(
		keyName = "highlightStyle",
		name = "Highlight style",
		description = "Highlight style for rocks and sprites (Outline, Hull, Tile, or Clickbox)",
		position = 21,
		section = renderingSection
	)
	default HighlightStyle highlightStyle()
	{
		return HighlightStyle.OUTLINE;
	}

	@Range(min = 1, max = 10)
	@ConfigItem(
		keyName = "outlineWidth",
		name = "Outline width",
		description = "Width of the highlight outline or border stroke",
		position = 22,
		section = renderingSection
	)
	default int outlineWidth()
	{
		return 2;
	}

	@ConfigSection(
		name = "Notifications",
		description = "Options for tray notifications",
		position = 30
	)
	String notificationsSection = "notificationsSection";

	@ConfigItem(
		keyName = "notifyRockDepleted",
		name = "Rock depleted",
		description = "Sends a notification when your Ascension rock has depleted",
		position = 31,
		section = notificationsSection
	)
	default Notification notifyRockDepleted()
	{
		return Notification.OFF;
	}

	@ConfigItem(
		keyName = "notifySpriteAppeared",
		name = "Sprite appeared",
		description = "Sends a notification when an Ascension sprite appears",
		position = 33,
		section = notificationsSection
	)
	default Notification notifySpriteAppeared()
	{
		return Notification.OFF;
	}
}

package com.ascensionshardmining;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Shape;
import java.awt.Stroke;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.WorldView;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

public class AscensionShardMiningOverlay extends Overlay
{
	private final Client client;
	private final AscensionShardMiningPlugin plugin;
	private final AscensionShardMiningConfig config;
	private final ModelOutlineRenderer modelOutlineRenderer;

	@Inject
	public AscensionShardMiningOverlay(
		Client client,
		AscensionShardMiningPlugin plugin,
		AscensionShardMiningConfig config,
		ModelOutlineRenderer modelOutlineRenderer)
	{
		super(plugin);
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.modelOutlineRenderer = modelOutlineRenderer;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final boolean highlightRocks = config.highlightRocks();
		final boolean highlightSprite = config.highlightSprite();

		if (!highlightRocks && !highlightSprite)
		{
			return null;
		}

		final Set<GameObject> activeRocks = plugin.getActiveRocks();
		final Set<NPC> sprites = plugin.getSprites();

		if ((!highlightRocks || activeRocks.isEmpty()) && (!highlightSprite || sprites.isEmpty()))
		{
			return null;
		}

		final WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return null;
		}

		final HighlightStyle style = config.highlightStyle();
		final int outlineWidth = config.outlineWidth();
		final Stroke stroke = (style != HighlightStyle.OUTLINE) ? new BasicStroke((float) outlineWidth) : null;
		final int currentPlane = worldView.getPlane();

		if (highlightRocks && !activeRocks.isEmpty())
		{
			final Color rockColor = config.rockColor();
			for (GameObject rock : activeRocks)
			{
				if (rock == null || rock.getPlane() != currentPlane)
				{
					continue;
				}

				renderGameObject(graphics, rock, rockColor, style, outlineWidth, stroke);
			}
		}

		if (highlightSprite && !sprites.isEmpty())
		{
			final Color spriteColor = config.spriteColor();

			for (NPC sprite : sprites)
			{
				if (sprite == null || sprite.isDead() || sprite.getWorldLocation().getPlane() != currentPlane)
				{
					continue;
				}

				renderNpc(graphics, sprite, spriteColor, style, outlineWidth, stroke);
			}
		}

		return null;
	}

	private void renderGameObject(Graphics2D graphics, GameObject object, Color color, HighlightStyle style, int outlineWidth, Stroke stroke)
	{
		switch (style)
		{
			case OUTLINE:
				modelOutlineRenderer.drawOutline(object, outlineWidth, color, 0);
				break;
			case HULL:
				Shape hull = object.getConvexHull();
				if (hull == null)
				{
					hull = object.getClickbox();
				}
				if (hull != null)
				{
					OverlayUtil.renderPolygon(graphics, hull, color, stroke);
				}
				break;
			case TILE:
				Polygon tilePoly = object.getCanvasTilePoly();
				if (tilePoly == null && object.getLocalLocation() != null)
				{
					tilePoly = Perspective.getCanvasTilePoly(client, object.getLocalLocation());
				}
				if (tilePoly != null)
				{
					OverlayUtil.renderPolygon(graphics, tilePoly, color, stroke);
				}
				break;
			case CLICKBOX:
				Shape clickbox = object.getClickbox();
				if (clickbox != null)
				{
					OverlayUtil.renderPolygon(graphics, clickbox, color, stroke);
				}
				break;
		}
	}

	private void renderNpc(Graphics2D graphics, NPC npc, Color color, HighlightStyle style, int outlineWidth, Stroke stroke)
	{
		switch (style)
		{
			case OUTLINE:
				modelOutlineRenderer.drawOutline(npc, outlineWidth, color, 0);
				break;
			case CLICKBOX:
			case HULL:
				Shape hull = npc.getConvexHull();
				if (hull != null)
				{
					OverlayUtil.renderPolygon(graphics, hull, color, stroke);
				}
				break;
			case TILE:
				Polygon tilePoly = npc.getCanvasTilePoly();
				if (tilePoly == null && npc.getLocalLocation() != null)
				{
					tilePoly = Perspective.getCanvasTilePoly(client, npc.getLocalLocation());
				}
				if (tilePoly != null)
				{
					OverlayUtil.renderPolygon(graphics, tilePoly, color, stroke);
				}
				break;
		}
	}
}

package com.ascensionshardmining;

import com.google.inject.Provides;
import java.util.Collections;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.NpcChanged;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.ObjectID;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Ascension Shard Mining",
	description = "Highlights active Ascension rocks and sprites for Ascension shard mining",
	tags = {"mining", "ascension", "shard", "rock", "sprite"}
)
public class AscensionShardMiningPlugin extends Plugin
{
	private static final Set<Integer> ACTIVE_ROCK_IDS = Set.of(
		ObjectID.TFA_GATHERING_ROCK_ACTIVE01,
		ObjectID.TFA_GATHERING_ROCK_ACTIVE02,
		ObjectID.TFA_GATHERING_ROCK_ACTIVE03
	);

	private static final Set<Integer> DEPLETED_ROCK_IDS = Set.of(
		ObjectID.TFA_GATHERING_ROCK_INACTIVE01,
		ObjectID.TFA_GATHERING_ROCK_INACTIVE02,
		ObjectID.TFA_GATHERING_ROCK_INACTIVE03
	);

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private AscensionShardMiningConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private AscensionShardMiningOverlay overlay;

	@Inject
	private Notifier notifier;

	@Getter(AccessLevel.PACKAGE)
	private final Set<GameObject> activeRocks = Collections.newSetFromMap(new ConcurrentHashMap<>());

	@Getter(AccessLevel.PACKAGE)
	private final Set<NPC> sprites = Collections.newSetFromMap(new ConcurrentHashMap<>());

	private WorldPoint targetRockLocation;

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(overlay);

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(() ->
			{
				WorldView worldView = client.getTopLevelWorldView();
				if (worldView != null)
				{
					for (NPC npc : worldView.npcs())
					{
						if (isSprite(npc))
						{
							sprites.add(npc);
						}
					}
				}
			});
		}
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(overlay);
		activeRocks.clear();
		sprites.clear();
		targetRockLocation = null;
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		int id = event.getId();
		if (ACTIVE_ROCK_IDS.contains(id))
		{
			WorldView wv = client.getTopLevelWorldView();
			if (wv != null)
			{
				targetRockLocation = WorldPoint.fromScene(wv, event.getParam0(), event.getParam1(), wv.getPlane());
				log.debug("Set target rock at {}", targetRockLocation);
			}
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		GameObject gameObject = event.getGameObject();
		if (gameObject == null)
		{
			return;
		}

		int id = gameObject.getId();
		if (ACTIVE_ROCK_IDS.contains(id))
		{
			activeRocks.add(gameObject);
		}
		else if (DEPLETED_ROCK_IDS.contains(id))
		{
			activeRocks.removeIf(rock ->
				rock.getWorldLocation().equals(gameObject.getWorldLocation())
				&& rock.getPlane() == gameObject.getPlane());

			checkRockDepleted(gameObject.getWorldLocation());
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		GameObject gameObject = event.getGameObject();
		if (gameObject == null)
		{
			return;
		}

		activeRocks.remove(gameObject);

		if (ACTIVE_ROCK_IDS.contains(gameObject.getId()))
		{
			checkRockDepleted(gameObject.getWorldLocation());
		}
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		NPC npc = event.getNpc();
		if (isSprite(npc))
		{
			sprites.add(npc);
			log.debug("Ascension sprite spawned: {}", npc);
			notifier.notify(config.notifySpriteAppeared(), "A Sprite has appeared!");
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		NPC npc = event.getNpc();
		if (npc != null)
		{
			sprites.remove(npc);
		}
	}

	@Subscribe
	public void onNpcChanged(NpcChanged event)
	{
		NPC npc = event.getNpc();
		if (isSprite(npc))
		{
			sprites.add(npc);

			if (event.getOld() == null || event.getOld().getId() != NpcID.TFA_GATHERING_SPRITE)
			{
				log.debug("Ascension sprite spawned: {}", npc);
				notifier.notify(config.notifySpriteAppeared(), "A Sprite has appeared!");
			}
		}
		else
		{
			sprites.remove(npc);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState gameState = event.getGameState();
		if (gameState == GameState.LOADING
			|| gameState == GameState.LOGIN_SCREEN
			|| gameState == GameState.HOPPING)
		{
			activeRocks.clear();
			sprites.clear();
			targetRockLocation = null;
		}
	}

	private void checkRockDepleted(WorldPoint location)
	{
		if (targetRockLocation != null && targetRockLocation.equals(location))
		{
			log.debug("Target rock depleted at {}", location);
			targetRockLocation = null;
			notifier.notify(config.notifyRockDepleted(), "Your Ascension rock has depleted");
		}
	}

	private static boolean isSprite(NPC npc)
	{
		return npc != null && npc.getId() == NpcID.TFA_GATHERING_SPRITE;
	}

	@Provides
	AscensionShardMiningConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AscensionShardMiningConfig.class);
	}
}

package com.ascensionshardmining;

public enum HighlightStyle
{
	OUTLINE,
	HULL,
	TILE,
	CLICKBOX
}

package com.ascensionshardmining;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class AscensionShardMiningPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(AscensionShardMiningPlugin.class);
		RuneLite.main(args);
	}
}
